      const y = c.P.ytr, ym = mean(y), SSEw = f.SSE, SSEo = f.SST, F = ((SSEo - SSEw) / q) / (SSEw / d2), p = ST.fSF(F, q, d2), Fc = fCrit(q, d2), R2 = 1 - SSEw / SSEo, adj = 1 - (1 - R2) * (N - 1) / d2;
